function processFrame(frame) {
  const active = detectActiveMics(frame);
  const W = whitening(frame, forgettingFactor);
  const strategy = chooseStrategy(active, sparsity(frame));
  const demixed = demix(frame, W, strategy);
  alignPermutation(demixed);
  return demixed;
}
```

